<template>
  <v-card class="pa-6 form-card">
    <div class="primary form-top-bar" />
    <v-card-title class="justify-center">
      <FormattedText
        intl
        type="text-h4"
        value="appInitialization.unfinishedRestoreTitle"
        class="mb-6"
      />
    </v-card-title>
    <v-list-item-avatar size="100" class="mb-0">
      <v-icon size="90">mdi-cloud-alert</v-icon>
    </v-list-item-avatar>
    <v-card-text class="text--primary">
      <FormattedText
        intl
        type="text-h6"
        value="appInitialization.unfinishedRestore"
        key="message"
        class="my-4"
      />
      <FormattedText
        type="text-h5"
        class="pt-4"
        className="font-weight-bold"
        color="textPrimary"
        value="ayuda@frogtek.org"
      />
    </v-card-text>
    <v-card-actions>
      <v-row class="d-flex justify-space-around">
        <v-col cols="5">
          <Button
            block
            large
            rounded
            @click="closeTT"
            intl
            text="posBlockedView.closeTT"
            textType="text-subtitle-2"
            textClass="text-capitalize"
          />
        </v-col>
        <v-col cols="5">
          <Button
            block
            large
            rounded
            @click="retryRestore"
            intl
            text="shared.retry"
            textType="text-subtitle-2"
            textClass="text-capitalize"
          />
        </v-col>
      </v-row>
    </v-card-actions>
  </v-card>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import RESTORE_EVENTS from '@/config/events/restore'
import LOGIN_EVENTS from '@/config/events/login'
import PUBSUB_EVENTS from '@/config/events/pubsub'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import accountActions from '@/store/account/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import Button from '@/components/shared/CustomButton'

export default {
  name: 'UnfinishedRestoreInfo',
  components: { FormattedText, Button },
  computed: {
    ...mapState('account', ['data']),
  },
  methods: {
    ...mapActions('account', [accountActions.setPosDataAfterLogin]),
    closeTT() {
      rendererEventsService.send('close-app')
    },
    retryRestore() {
      rendererEventsService.send(RESTORE_EVENTS.channel, {
        event: RESTORE_EVENTS.events.rollbackRestore.name,
        data: { online: navigator.onLine },
      })
    },
    restoreListener(event, payload) {
      this.restoring = true
      const replies = {
        [RESTORE_EVENTS.events.rollbackRestore.replies.success]: () => {
          rendererEventsService.send(LOGIN_EVENTS.channel, {
            event: LOGIN_EVENTS.events.loginFromUnfinishedRestore.name,
            data: { online: navigator.onLine, posData: payload.data },
          })
        },
        [RESTORE_EVENTS.events.rollbackRestore.replies.error]: () => {
          notificationsService.showError(
            'appInitialization.unfinishedRestoreError',
            this.$vuetify.lang,
            { timeout: 10000 }
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    loginListener(event, payload) {
      const replies = {
        [LOGIN_EVENTS.events.loginFromUnfinishedRestore.replies
          .success]: () => {
          rendererEventsService.send(PUBSUB_EVENTS.channel, {
            event: PUBSUB_EVENTS.events.updatePosInfo.name,
            data: {
              country: this.data.country.phoneCode,
              pos: payload.data.pos,
            },
          })
          this.loginProcess = true
          this[accountActions.setPosDataAfterLogin]({
            posData: payload.data,
            pendingSyncOps: 1,
          })
          this.$track({
            type: 'system',
            action: 'api_call',
            category: 'Signup',
            screen: 'UnfinishedRestore',
            name: 'Start restore process',
          })
          rendererEventsService.send(RESTORE_EVENTS.channel, {
            event: RESTORE_EVENTS.events.restoreProcess.name,
            data: { posData: payload.data },
          })
          this.$router.push({ name: 'Restore' })
        },
        [LOGIN_EVENTS.events.loginFromUnfinishedRestore.replies.error]: () => {
          notificationsService.showError(
            'appInitialization.unfinishedRestoreError',
            this.$vuetify.lang,
            { timeout: 10000 }
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  mounted() {
    rendererEventsService.subscribe(
      RESTORE_EVENTS.replyChannel,
      this.restoreListener
    )
    rendererEventsService.subscribe(
      LOGIN_EVENTS.replyChannel,
      this.loginListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      RESTORE_EVENTS.replyChannel,
      this.restoreListener
    )
    rendererEventsService.removeListener(
      LOGIN_EVENTS.replyChannel,
      this.loginListener
    )
  },
}
</script>

<style lang="scss" scoped>
.form-card {
  border-radius: 8px !important;
  position: relative;
  .form-top-bar {
    height: 8px;
    width: 100%;
    position: absolute;
    top: 0;
    left: 0;
  }
}
</style>
